if (checkpointContents !== undefined) {
  try {
    const checkpoint = JSON.parse(checkpointContents);
    if (!checkpoint || !Number.isSafeInteger(checkpoint.nextLine) || checkpoint.nextLine < 0) {
      throw new Error('Invalid checkpoint nextLine');
    }
    nextLine = checkpoint.nextLine;
  } catch {
    // Preserve the exact corrupt bytes before replaying. Exclusive creation
    // keeps evidence from earlier recoveries intact as well.
    const contents = await readFile(checkpointPath);
    let backupPath = `${checkpointPath}.corrupt`;
